    if target not in graph or any((weight < 0 for edge in graph.values() for weight in edge)):
        return (float('inf'), None)
    queue = [(0, [source], source)]
    visited = set()
    while queue:
        current_distance, current_path, current_node = queue.pop(0)
        if current_node not in visited:
            visited.add(current_node)
            if current_node == target:
                return (current_distance, current_path)
            for neighbor, weight in graph.get(current_node, []):
                if neighbor not in visited:
                    new_distance = current_distance + weight
                    new_path = current_path + [neighbor]
                    queue.append((new_distance, new_path, neighbor))
    return (float('inf'), None)

