    distances: Dict[Any, Union[int, float]] = {node: inf for node in graph}
    paths: Dict[Any, List[Any]] = {node: [] for node in graph}
    distances[source] = 0
    paths[source] = [source]

    def to_adj_list(graph: Dict[Any, List[Tuple[Any, Union[int, float]]]]) -> Dict[Any, List[Tuple[Any, Union[int, float]]]]:
        adj_list: Dict[Any, List[Tuple[Any, Union[int, float]]]] = defaultdict(list)
        for node, neighbors in graph.items():
            for neighbor, weight in neighbors:
                adj_list[node].append((neighbor, weight))
        return adj_list
    adj_list = to_adj_list(graph)
    for _ in range(len(graph) - 1):
        for node, neighbors in adj_list.items():
            for neighbor, weight in neighbors:
                if distances[node] + weight < distances[neighbor]:
                    distances[neighbor] = distances[node] + weight
                    paths[neighbor] = paths[node] + [neighbor]
    for node, neighbors in adj_list.items():
        for neighbor, weight in neighbors:
            if distances[node] + weight < distances[neighbor]:
                raise ValueError('Graph contains a negative-weight cycle.')
    return (distances[target], paths[target]) if target in distances else (float('inf'), None)

